<section class="overflow-hidden rounded-lg border border-border bg-surface" x-data="{step:0, steps:[['👀','Observar','Comprobá atrás, adelante y hacia los lados.'],['🐢','Reducir','Prepará la velocidad antes de soltar una mano.'],['👈','Señalar','Comunicá con anticipación sin perder la trayectoria.'],['🙌','Controlar','Volvé la mano al manubrio antes de girar.']]}">
    <header class="border-b border-border px-4 py-3"><p class="text-xs font-bold uppercase tracking-wide text-primary">Ensayo de comunicación</p><h4 class="mt-1 font-heading text-lg font-bold">Una señal comienza antes de mover el brazo</h4></header>
    <div class="grid min-h-52 place-items-center bg-amber-100 p-5 text-center text-slate-900" role="img" :aria-label="steps[step][1]+'. '+steps[step][2]"><div><span class="text-7xl" aria-hidden="true" x-text="steps[step][0]"></span><span class="mt-2 block text-5xl" aria-hidden="true">🚲</span></div></div>
